pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.deal(sender, amount);
        uint256 beforeCount = c.depositsCount();
        bool ok;
        vm.prank(sender);
        try c.receive{value: amount}() { ok = true; } catch { ok = false; }
        uint256 afterCount = c.depositsCount();
        // If the call succeeded, depositsCount must increase by exactly 1.
        // If the call failed, depositsCount must remain unchanged.
        // The reference accepts all msg.value including 0, so for amount == 0, ok is true and afterCount == beforeCount + 1.
        // The bug rejects amount == 0, so for amount == 0, ok is false and afterCount == beforeCount, violating the case where ok is true.
        assertTrue(!ok || afterCount == beforeCount + 1);
    }
}

