contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Restrict deposit amount to 1 ether to have a clean invariant linking balance and depositsCount
        bound(depositAmount, 1 ether, 1 ether);

        // Record balance and depositsCount before the receive
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // Send Ether to trigger receive()
        address sender = address(0x1234);
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: depositAmount}("");

        // The general rule:
        // After a receive() call, the balance must increase by exactly depositAmount,
        // and depositsCount must increase by exactly 1.
        // Equivalently: new_balance == old_balance + depositAmount
        // AND new_deposits == old_deposits + 1.
        // Assert both together as a single boolean expression.
        assertTrue(
            (address(c).balance == balanceBefore + depositAmount) &&
            (c.depositsCount() == depositsBefore + 1)
        );
    }
}

