pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address target, address nonOwner) public {
        // Restrict amount so that sendMoney doesn't revert due to insufficient balance after funding.
        vm.assume(amount > 0 && amount <= address(c).balance);
        // Ensure target and nonOwner are distinct from owner and each other, and not the zero address.
        vm.assume(target != address(0) && nonOwner != address(0));
        vm.assume(nonOwner != c.owner() && target != nonOwner);

        // Fund the contract and the nonOwner.
        vm.deal(address(c), amount * 2);
        vm.deal(nonOwner, 0.1 ether);

        // Owner sends money.
        vm.prank(c.owner());
        c.sendMoney(target, amount);

        uint balanceBefore = address(c).balance;

        // Non-owner attempts to withdrawAll. Reference should revert (balance unchanged),
        // buggy should succeed (balance becomes 0).
        vm.prank(nonOwner);
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Reference: non-owner call reverts, balance unchanged -> ok is false, balanceBefore == address(c).balance.
        // Buggy: non-owner call succeeds, balance drained -> ok is true, balanceBefore != address(c).balance (it's 0).
        // The rule: if the call reverts, balance must not change; if it succeeds, the balance must decrease.
        // Combined: either ok is false AND balance unchanged, OR ok is true AND balance decreased.
        // More simply, for the reference, ok must be false, so we can assert that the combination is true:
        // ok == false || (ok == true && address(c).balance < balanceBefore).
        // But the universal property for the reference is: non-owner cannot withdraw -> ok is always false.
        assertTrue(!ok);
    }
}
// No adversarial helper needed: the difference manifests via a non-owner calling withdrawAll directly.

