import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        // ensure nonOwner is not the contract owner who deployed C
        vm.assume(nonOwner != address(this));
        // bound amount to a reasonable range that can be sent
        amount = bound(amount, 0, 1 ether);
        // record initial balance of the owner (this contract is the owner because setUp deploys C)
        address ownerAddr = address(this);
        uint256 ownerInitialBalance = ownerAddr.balance;
        // give the nonOwner some ether
        vm.deal(nonOwner, amount + 0.1 ether);
        // send ether to C so it has a balance to steal
        vm.deal(address(c), 1 ether);
        // nonOwner calls sendMoney to themselves with the contract's balance minus 1 wei
        uint256 stealAmount = address(c).balance > 0 ? address(c).balance - 1 : 0;
        vm.prank(nonOwner);
        c.sendMoney(nonOwner, stealAmount);
        // now the owner (this contract) calls withdrawAll
        c.withdrawAll();
        uint256 ownerFinalBalance = ownerAddr.balance;
        // Assert: the owner's final balance should be equal to their initial balance + the original contract balance
        // because only the owner should be able to withdraw funds; any other caller spending is a violation.
        // The correct contract would have reverted the nonOwner's sendMoney, so the owner withdraws the full contract balance.
        // The buggy contract allows the nonOwner to drain funds, so the owner ends up with less.
        assertEq(ownerFinalBalance, ownerInitialBalance + 1 ether);
    }
}

